INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 1, 'theory', 'Quiz: Complexity Analysis');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 1, 0, 'A quadratic algorithm was rewritten in the fastest language in the world, while a logarithmic algorithm stayed in the slowest. Which one wins on a million elements?', '["The quadratic one in the fast language: constants decide", "The logarithmic one: about twenty operations against a trillion, growth class beats language", "Both about the same: the language evens everything out", "It depends on the amount of RAM"]', 1, 'On a million elements a logarithm is tens of operations and a quadratic is trillions, which means a fraction of a second against hours. The growth class beats the language, the hardware, and any small tricks.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 1, 1, 'Why do library sorts switch to simple methods on small pieces?', '["Simple methods need no extra memory", "The language standard requires supporting old algorithms", "Big-O drops constants: on small data an algorithm with a smaller constant but a worse class can win", "Complex algorithms do not work on short arrays"]', 2, 'Big-O answers the question of what happens on big data, not which is faster on ten elements. Both questions are legitimate; just do not mix up which one each measure answers.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 1, 2, 'Quicksort runs on already sorted data and picks the first element as the pivot. What happens?', '["Every partition splits the array into one element and the rest, and the complexity slides down to quadratic", "The sort finishes in linear time: the data is already ordered", "Nothing changes: the complexity stays n log n", "The recursion stack is bound to overflow"]', 0, 'The recursion depth becomes linear. There are three remedies: a random pivot, a median of three, or an introspective approach that switches to a sort immune to bad data.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 1, 3, 'In which case is the phrase “a dictionary works in constant time” dangerous?', '["If the keys are short strings", "If the table has just been created and is empty", "If there are few operations on the table", "If your keys all pile up in one bucket, so lookup becomes linear"]', 3, 'An averaged constant with a rare linear failure is a fair deal if you never hit the failure, and a dangerous one if your keys guarantee it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 1, 4, 'A dynamic array sometimes spends linear time on an append, yet is considered constant. Why is that fair?', '["Because copying is done by a special fast processor instruction", "Because rare expensive copies, spread over many inserts, give a constant on average", "Because memory for the array is allocated far ahead of time", "Because copying is not part of the operation''s complexity"]', 1, 'Amortized analysis divides the total work by the number of operations. The same logic applies to hash tables when they resize and to garbage collectors.');
